INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q106839672', 'Danish Civil Wars', 'The Danish Civil Wars (Danish: Kongekrigene, Norwegian: De danske kongekrige) were a series of civil wars fought in the Kingdom of Denmark, first from 1131 to 1134 over the murder of Canute Lavard, then from 1139 to 1143, and finally a war of succession fought from 1146 to 1157, after the abdication of Eric III of Denmark, the first monarch in Danish history to have abdicated. The first phase of the war was fought between King Eric II of Denmark and King Niels joined by Magnus the Strong.', 1131, NULL, NULL, 1157, NULL, NULL, 'year', '1131–1157', 34, 'https://en.wikipedia.org/wiki/Danish_Civil_Wars'),
  ('Q3267709', 'Battle of Grathe Heath', 'The Battle of Grathe Heath was the last major battle of the Danish Civil Wars, being fought on 23 October 1157 at the Jutland Peninsula between the armies of Valdemar I and his rival for the Danish throne, Sweyn III. Valdemar''s forces won the battle, and Sweyn was slain while attempting to flee.', 1157, NULL, NULL, NULL, NULL, NULL, 'year', '1157', 43, 'https://en.wikipedia.org/wiki/Battle_of_Grathe_Heath'),
  ('Q11956522', '6000-Mark War', 'The 6000-mark war (Swedish: 6000-markskriget, Danish: 6000-marks-krigen) was a war between Denmark and Sweden which took place from 1276 to 1278. It started because of a disagreement over an agreed sum of 6,000 silver marks for Danish assistance to Magnus Birgersson in the battle against Valdemar Birgersson in 1275.', 1276, NULL, NULL, 1278, NULL, NULL, 'year', '1276–1278', 37, 'https://en.wikipedia.org/wiki/6000-mark_war'),
  ('Q17750244', 'Treaty of Bergen', 'Treaty of Bergen, signed on 29 August 1450 in Bergen, between Norway and Denmark. The agreement was in many ways a continuation of the Kalmar Union founded in 1397, between Norway, Denmark and Sweden, while Norway and Denmark had been in a personal union with a common king since 1380 (with interruptions).', 1450, 8, 29, NULL, NULL, NULL, 'day', '29 August 1450', 30, 'https://en.wikipedia.org/wiki/Treaty_of_Bergen'),
  ('Q742137', 'Battle of Bornholm', 'The Battle of Bornholm was a naval battle which took place near the Danish island of Bornholm, between privateers from the city of Gdańsk (Danzig) and a transport convoy of Danish and Livonian ships which were attempting to bring supplies and reinforcements to the Teutonic Knights in Prussia, during the Thirteen Years'' War (1454–66) between the Kingdom of Poland and the Prussian Confederation on one hand, and the Monastic State of the Teutonic Knights on the other. The battle took place on the night of 14 August 1457.', 1456, NULL, NULL, NULL, NULL, NULL, 'year', '1456', 37, 'https://en.wikipedia.org/wiki/Battle_of_Bornholm_(1457)'),
  ('Q478059', 'Treaty of Ribe', 'The Treaty of Ribe (Danish: Ribe-brevet, transl. The Ribe letter; German: Vertrag von Ripen) was a proclamation at Ribe made in 1460 by King Christian I of Denmark to a number of Holsatian nobles enabling himself to become Count of Holstein and gain control of the Duchy of Schleswig, on Denmark''s southern border. The most famous line of the proclamation was that the Danish Duchy of Schleswig and the County of Holstein within the Holy Roman Empire, should now be, in the original Middle Low German language, Up Ewig Ungedeelt, or "Forever Undivided".', 1460, 3, 5, NULL, NULL, NULL, 'day', '5 March 1460', 43, 'https://en.wikipedia.org/wiki/Treaty_of_Ribe'),
  ('Q1606958', 'Battle of Bogesund', 'The Battle of Bogesund was an important conflict in the campaign of Christian II to gain power over Sweden. In 1520, Christian''s army of mercenaries had landed in Sweden, seeking to consolidate Christian''s powers over Sweden within the Kalmar Union and to unseat the rebellious Swedish riksföreståndare Sten Sture the Younger.', 1520, 1, 19, NULL, NULL, NULL, 'day', '19 January 1520', 43, 'https://en.wikipedia.org/wiki/Battle_of_Bogesund'),
  ('Q2890945', 'Battle of Axtorna', 'The Battle of Axtorna or simply Axtorna, was fought between the Kingdom of Sweden and Denmark–Norway 20 October 1565 at Axtorna, a small village in what is today Falkenberg Municipality, Halland County in south-western Sweden.', 1565, 10, 20, NULL, NULL, NULL, 'day', '20 October 1565', 41, 'https://en.wikipedia.org/wiki/Battle_of_Axtorna'),
  ('Q392121', 'Battle of Fehmarn', 'The battle of Fehmarn took place north-west of the island of Fehmarn, now part of Germany, in the Baltic Sea. A combined Swedish fleet, with a large element of hired Dutch ships, defeated a Danish fleet and took 1,000 prisoners, including Ulfeldt, Benjamin Grabov and von Jasmund.', 1644, 10, 13, NULL, NULL, NULL, 'day', '13 October 1644', 48, 'https://en.wikipedia.org/wiki/Battle_of_Fehmarn_(1644)'),
  ('Q423522', 'Battle of Colberger Heide', 'The Battle of Colberger Heide (also Kolberger Heide or Colberg Heath) took place on 1 July 1644 during the Torstenson War, off the coast of Schleswig-Holstein. The battle was indecisive, but a minor success for the Dano-Norwegian fleet commanded by Jørgen Vind, assisted by Grabow and King Christian IV, over a Swedish fleet commanded by Klas Fleming, assisted by Ulfsparre and Bjelkenstjerna.', 1644, 7, 1, NULL, NULL, NULL, 'day', '1 July 1644', 45, 'https://en.wikipedia.org/wiki/Battle_of_Colberger_Heide'),
  ('Q551218', 'Action of 16 May 1644', 'This battle took place on 16 May 1644 during the Torstenson War near List Deep, between Sylt and Rømø in western Denmark. Nine Danish ships under King Christian IV forced a retreat back into List Deep of 26 smaller Dutch ships (13 under Marten Thijsen and 13 under Hendrik Gerritsen) which had been leased to Sweden.', 1644, 5, 16, NULL, NULL, NULL, 'day', '16 May 1644', 43, 'https://en.wikipedia.org/wiki/Battle_of_Listerdyb'),
  ('Q541566', 'Battle of Kolding', 'The siege of Kolding was fought on December 25, 1658, between Sweden and the forces of the Polish–Lithuanian Commonwealth and Denmark–Norway. The Polish and Danish forces were led by Stefan Czarniecki.', 1658, 12, 25, NULL, NULL, NULL, 'day', '25 December 1658', 47, 'https://en.wikipedia.org/wiki/Siege_of_Kolding_(1658)'),
  ('Q647694', 'March Across the Belts', 'The March Across the Belts (Swedish: Tåget över Bält) was a military campaign waged by the Swedish Empire across the ice between the Danish islands. It lasted between 30 January and 15 February 1658, ending with a decisive victory for Swedish King Charles X Gustav during his first Danish war.', 1658, 1, 30, 1658, 2, 6, 'day', '30 January 1658 – 6 February 1658', 47, 'https://en.wikipedia.org/wiki/March_Across_the_Belts'),
  ('Q1275200', 'Battle of the Sound', 'The Battle of the Sound was a naval engagement which took place on 8 November 1658 (29 October O.S.) during the Second Northern War, near the Sound or Øresund, just north of the Danish capital, Copenhagen. Sweden had invaded Denmark and an army under Charles X Gustav of Sweden had Copenhagen itself under siege.', 1658, 10, 29, NULL, NULL, NULL, 'day', '29 October 1658', 52, 'https://en.wikipedia.org/wiki/Battle_of_the_Sound'),
  ('Q10488994', 'Siege of Kronborg', 'The siege of Kronborg (Danish: Belejringen af Kronborg; Swedish: Belägring av Kronborg) was a Swedish siege of the Danish stronghold Kronborg from 16 August to 6 September 1658, during the Dano-Swedish War of 1658–1660. The siege ended with a Swedish victory.', 1658, 8, 16, 1658, 9, 6, 'day', '16 August 1658 – 6 September 1658', 34, 'https://en.wikipedia.org/wiki/Siege_of_Kronborg'),
  ('Q641989', 'Battle of Nyborg', 'The Battle of Nyborg took place between Sweden and the combined forces of Denmark, Dutch naval forces under Michiel de Ruyter, troops of Brandenburg-Prussia, and Polish–Lithuanian Commonwealth forces under Stefan Czarniecki. The battle was engaged on 14 November 1659 at Nyborg on the Danish island of Funen.', 1659, 11, 14, NULL, NULL, NULL, 'day', '14 November 1659', 48, 'https://en.wikipedia.org/wiki/Battle_of_Nyborg'),
  ('Q2567011', 'Assault on Copenhagen', 'The assault on Copenhagen (Danish: stormen på København; Swedish: stormningen av Köpenhamn), also known as the battle of Copenhagen, on 11 February 1659, was a major engagement during the Second Northern War, taking place during the Swedish siege of Copenhagen. Following the arrival of Swedish forces on Zealand on 7 August 1658, they intended to attack Copenhagen, thus conquering Denmark.', 1659, 2, 11, NULL, NULL, NULL, 'day', '11 February 1659', 39, 'https://en.wikipedia.org/wiki/Assault_on_Copenhagen_(1659)'),
  ('Q829702', 'Treaty of Copenhagen', 'The Treaty of Copenhagen (Danish: Freden i København, Swedish: Freden i Köpenhamn) was signed on 27 May 1660, and marked the conclusion of the Second Northern War between the Swedish Empire and the alliance of Denmark–Norway and the Polish–Lithuanian Commonwealth. This treaty was a smaller follow-up treaty to that of the Treaty of Roskilde, which decisively delineated the mutually recognized boundaries of Denmark, Sweden, and Norway; boundaries which are almost exactly the same to this day.', 1660, 5, 27, NULL, NULL, NULL, 'day', '27 May 1660', 64, 'https://en.wikipedia.org/wiki/Treaty_of_Copenhagen_(1660)'),
  ('Q2265621', 'Battle of Køge Bay', 'The Battle of Køge Bay was a naval battle between Denmark-Norway and Sweden that took place in the bay off of Køge 1–2 July 1677 during the Scanian War. The battle was a major success for Admiral Niels Juel after his previous victory one month earlier at the Battle of Møn, and is regarded as the greatest victory in Danish naval history.', 1677, NULL, NULL, 1677, 7, 2, 'year', '1677', 48, 'https://en.wikipedia.org/wiki/Battle_of_K%C3%B8ge_Bay_(1677)'),
  ('Q2888498', 'Battle of Møn', 'The Battle of Møn, also known as the Battle of Fehmarn, took place 31 May–1 June 1677, as part of the Scanian War. A smaller Swedish squadron under Admiral Erik Sjöblad attempted to sail from Gothenburg to join the main Swedish fleet in the Baltic Sea.', 1677, 5, 31, 1677, 6, 1, 'day', '31 May 1677 – 1 June 1677', 39, 'https://en.wikipedia.org/wiki/Battle_of_M%C3%B8n'),
  ('Q4582269', 'Siege of Malmö', 'The siege of Malmö (Swedish: Belägringen av Malmö) was an unsuccessful Danish siege on the Swedish-held city of Malmö, fought between June 11 and July 5, 1677. Fought towards the end of the Scanian War, the siege was one in a string of Danish losses that saw Swedish forces under King Charles XI of Sweden establish control over the southern region of Sweden.', 1677, 6, 11, 1677, 7, 5, 'day', '11 June 1677 – 5 July 1677', 43, 'https://en.wikipedia.org/wiki/Siege_of_Malm%C3%B6'),
  ('Q5423108', 'Battle of Humlebæk', 'The Landing at Humlebæk took place on 4 August 1700 (N.S.), commencing the Swedish invasion of Denmark during the Great Northern War 1700–1721. It was the first offensive during the war by the Swedish army, and it was directly led by Charles XII of Sweden commanding the right flank and Arvid Horn together with Carl Gustav Rehnskiöld at the left.', 1700, 8, 4, NULL, NULL, NULL, 'day', '4 August 1700', 34, 'https://en.wikipedia.org/wiki/Landing_at_Humleb%C3%A6k'),
  ('Q2331686', 'Treaty of Copenhagen', 'On 22 October 1709, during the Great Northern War, the alliance between the Russian Empire and Denmark-Norway was renewed in the Treaty of Copenhagen. Charles XII of Sweden had destroyed the previous alliance in Travendal (1700).', 1709, 10, 11, NULL, NULL, NULL, 'day', '11 October 1709', 48, 'https://en.wikipedia.org/wiki/Treaty_of_Copenhagen_(1709)'),
  ('Q1446460', 'Action of 4 October 1710', 'The Battle of Køge Bay, also known to as the Second Battle of Køge Bay, was an indecisive battle that took place on 4 October 1710 (N.S.) during the Great Northern War in Køge Bay (Danish: Køge Bugt), just south of Copenhagen. Denmark had 26 ships of the line and 5 frigates with 1808 guns, and Sweden had 21 ships of the line and several frigates with 1512 guns.', 1710, 10, 4, NULL, NULL, NULL, 'day', '4 October 1710', 41, 'https://en.wikipedia.org/wiki/Battle_of_K%C3%B8ge_Bay_(1710)'),
  ('Q708866', 'Battle of Gadebusch', 'The Battle of Gadebusch or Wakenstädt (20 December 1712) was Sweden''s final great victory in the Great Northern War. It was fought by the Swedes to prevent the loss of the city of Stralsund to Danish and Saxon forces.', 1712, 12, 20, NULL, NULL, NULL, 'day', '20 December 1712', 52, 'https://en.wikipedia.org/wiki/Battle_of_Gadebusch'),
  ('Q28949606', 'Danish–Algerian War', 'The Dano-Algerian War (Danish: Krigen mellem Danmark-Norge og Algier, Arabic: قصف الجزائر) was a conflict lasting from 1769 to 1772 between Denmark–Norway and the Regency of Algiers. The latter of which was functionally and mostly independent from the Ottoman Empire.', 1769, 9, 14, 1772, 5, 16, 'day', '14 September 1769 – 16 May 1772', 45, 'https://en.wikipedia.org/wiki/Dano-Algerian_War'),
  ('Q3352530', 'Copenhagen Fire of 1795', 'The Copenhagen Fire of 1795 (Københavns brand 1795) started on Friday, 5 June 1795, at or around 3 pm by the Navy''s old base south east of Kongens Nytorv on Gammelholm, in the Navy''s magazine for coal and timber, the so-called Dellehave. As the workers had already gone home, a considerable length of time passed before efforts to combat the fire started, and out of fear of theft, the fire hydrants had been removed.', 1795, NULL, NULL, NULL, NULL, NULL, 'year', '1795', 43, 'https://en.wikipedia.org/wiki/Copenhagen_Fire_of_1795'),
  ('Q755955', 'Battle of Copenhagen', 'In the Battle of Copenhagen, also known as the First Battle of Copenhagen to distinguish it from the Second Battle of Copenhagen in 1807, a British naval fleet defeated a smaller force of the Royal Dano-Norwegian Navy anchored near Copenhagen on 2 April 1801. The battle came about over British fears that the powerful Danish fleet would ally with France, and a breakdown in diplomatic communications on both sides.', 1801, 4, 2, NULL, NULL, NULL, 'day', '2 April 1801', 66, 'https://en.wikipedia.org/wiki/Battle_of_Copenhagen_(1801)'),
  ('Q376154', 'Battle of Copenhagen', 'The Battle of Copenhagen (also known as the Bombardment of Copenhagen) occurred between 16 August and 7 September 1807 during the Napoleonic Wars. British forces bombarded the Danish capital of Copenhagen in order to capture or destroy the Royal Dano-Norwegian Navy.', 1807, NULL, NULL, 1807, 9, 5, 'year', '1807', 63, 'https://en.wikipedia.org/wiki/Battle_of_Copenhagen_(1807)'),
  ('Q3430256', 'Battle of Køge', 'The Battle of Køge was fought on 29 August 1807 between British troops besieging Copenhagen and Danish militia raised on Sjælland as part of the Gunboat War. It ended in a British victory and is also known as ''Træskoslaget'' or ''the Clogs Battle'', since many of the Danish militiamen threw their heavy wooden clogs away when they were fleeing.', 1807, 8, 29, NULL, NULL, NULL, 'day', '29 August 1807', 39, 'https://en.wikipedia.org/wiki/Battle_of_K%C3%B8ge'),
  ('Q3432591', 'Battle of Zealand Point', 'The Battle of Zealand Point was fought off Zealand on 22 March 1808 during the Gunboat War. Three ships of the line and one frigate of the Royal Navy intercepted and destroyed a Danish ship of the line.', 1808, 3, 22, NULL, NULL, NULL, 'day', '22 March 1808', 37, 'https://en.wikipedia.org/wiki/Battle_of_Zealand_Point'),
  ('Q514504', 'Battle of Sehested', 'The Battle of Sehested was fought on 10 December 1813 during the Dano-Swedish War of 1813–1814 between a Danish army under Prince Frederik of Hesse and a Coalition force led by Ludwig von Wallmoden-Gimborn. Near Sehested, Holstein, Frederik''s troops defeated the Coalition army, inflicting over 1,100 casualties on von Wallmoden-Gimborn''s force while suffering only 500.', 1813, 12, 13, NULL, NULL, NULL, 'day', '13 December 1813', 43, 'https://en.wikipedia.org/wiki/Battle_of_Sehested'),
  ('Q11965447', 'Battle of Dybbøl', 'The First Battle of Dybbøl was the first of three battles of the First War of Schleswig to be fought at the town of Dybbøl between the Danish army and forces of Prussia and the other German states.', 1848, NULL, NULL, NULL, NULL, NULL, 'year', '1848', 34, 'https://en.wikipedia.org/wiki/Battle_of_Dybb%C3%B8l_(1848)'),
  ('Q11988463', 'March Revolution (Denmark)', 'The March Revolution in Denmark are the events of 1848 that ultimately led to the introduction of Danish constitutional monarchy and the Constitution of Denmark.', 1848, 3, NULL, NULL, NULL, NULL, 'month', 'March 1848', 41, 'https://en.wikipedia.org/wiki/March_Revolution_(Denmark)'),
  ('Q12001392', 'Battle of Nybøl', 'The Battle of Nybøl was fought on 28 May 1848 between the Danish Army and Germans in Sundeved. The Danes were victorious.', 1848, 5, 28, NULL, NULL, NULL, 'day', '28 May 1848', 41, 'https://en.wikipedia.org/wiki/Battle_of_Nyb%C3%B8l'),
  ('Q4587924', 'Battle of Fredericia', 'The Battle of Fredericia was fought between soldiers of Schleswig-Holstein and Denmark on 6 July 1849 at Fredericia in Denmark. The battle was part of the First Schleswig War, which was a conflict between Schleswig-Holstein, supported by several German states, and Denmark.', 1849, 7, 6, NULL, NULL, NULL, 'day', '6 July 1849', 43, 'https://en.wikipedia.org/wiki/Battle_of_Fredericia'),
  ('Q12001379', 'Battle of Kolding', 'The Battle of Kolding was a battle during the First Schleswig War fought between a Prussian army under Eduard von Bonin and a Danish army under Frederik Rubeck Bülow in Kolding, Denmark on 23 April 1849. The Prussians were victorious and the Danish army was forced to retreat towards Vejle and Fredericia.', 1849, 4, 23, NULL, NULL, NULL, 'day', '23 April 1849', 37, 'https://en.wikipedia.org/wiki/Battle_of_Kolding_(1849)'),
  ('Q9360744', 'Copenhagen Convention of 1857', 'The Copenhagen Convention, which came into force on 14 March 1857, is a maritime treaty governing transit passage through the Danish Straits.', 1857, 3, 14, NULL, NULL, NULL, 'day', '14 March 1857', 39, 'https://en.wikipedia.org/wiki/Copenhagen_Convention_of_1857'),
  ('Q154981', 'Second Schleswig War', 'The Second Schleswig War or German-Danish War, also sometimes known as the Dano-Prussian War or Prusso-Danish War, was the second military conflict over the Schleswig–Holstein question of the 19th century. The war began on 1 February 1864, when Prussian and Austrian forces crossed the border into the Danish fief Schleswig.', 1864, 2, 1, 1864, 10, 31, 'day', '1 February 1864 – 31 October 1864', 75, 'https://en.wikipedia.org/wiki/Second_Schleswig_War'),
  ('Q695107', 'Battle of Dybbøl', 'The Battle of Dybbøl (Danish: Slaget ved Dybbøl; German: Erstürmung der Düppeler Schanzen) was the key battle of the Second Schleswig War, fought between Denmark and Prussia. The battle was fought on the morning of 18 April 1864, following a siege that began on 2 April.', 1864, 4, 18, NULL, NULL, NULL, 'day', '18 April 1864', 57, 'https://en.wikipedia.org/wiki/Battle_of_Dybb%C3%B8l'),
  ('Q1434879', 'Battle of Als', 'The Battle of Als (Danish: Slaget om Als; German: Übergang nach Alsen) was fought on 29 June 1864 during the Second Schleswig War between Denmark and Prussia. It was the last major engagement of the war, as the Prussians under General Herwarth von Bittenfeld secured the island of Als – occupied by 9,000 Danish troops, including the garrison of Dybbøl which had retreated there – in a night attack masterminded by the Chief of Staff (later Field Marshal) Leonhard Graf von Blumenthal.', 1864, 6, 29, 1864, 7, 1, 'day', '29 June 1864 – 1 July 1864', 41, 'https://en.wikipedia.org/wiki/Battle_of_Als'),
  ('Q4871618', 'Battle of Lundby', 'The Battle of Lundby took place south of Lundby in northeast Himmerland on 3 July 1864 in the Second Schleswig War. A Danish company of the First Regiment tried a head-on bayonet charge down a long hillside towards a Prussian company, but was stopped 20 meters in front of the earth dike that the Prussians lay in cover behind.', 1864, 7, 3, NULL, NULL, NULL, 'day', '3 July 1864', 34, 'https://en.wikipedia.org/wiki/Battle_of_Lundby'),
  ('Q5258024', 'Denmark–Korea Treaty of 1902', 'The Denmark–Korea Treaty of 1902 was negotiated between representatives of the Kingdom of Denmark and the Korean Empire.', 1902, NULL, NULL, NULL, NULL, NULL, 'year', '1902', 30, 'https://en.wikipedia.org/wiki/Denmark%E2%80%93Korea_Treaty_of_1902'),
  ('Q2461927', 'Danish West Indian Islands sale referendum', 'A referendum on the sale of the Danish West Indian Islands to the United States of America was held in Denmark on 14 December 1916. The non-binding referendum saw 283,670 vote in favor of the sale of the Danish West Indian Islands and 158,157 against.', 1916, 12, 14, NULL, NULL, NULL, 'day', '14 December 1916', 39, 'https://en.wikipedia.org/wiki/1916_Danish_West_Indian_Islands_sale_referendum'),
  ('Q150939', 'Operation Weserübung', 'Operation Weserübung (Unternehmen Weserübung [ˈveːzɐˌʔyːbʊŋ], (German: "Operation Weser Exercise") was the invasion of Denmark and Norway by Nazi Germany during World War II. Taking place from 9 April – 10 June 1940, it was the opening operation of the Norwegian Campaign. In the early morning of 9 April 1940 (Wesertag, "Weser Day"), German forces occupied Denmark and invaded Norway, ostensibly as a preventive manoeuvre against a planned Anglo-French occupation of Norway known as Plan R 4, which developed as a response to a German invasion of Norwegian territory.', 1940, NULL, NULL, 1940, 6, 10, 'year', '1940', 75, 'https://en.wikipedia.org/wiki/Operation_Weser%C3%BCbung'),
  ('Q16470', 'Normandy landings', 'The Normandy landings were the landing operations and associated airborne operations on 6 June 1944 of the Allied invasion of Normandy in Operation Overlord during the Second World War. Codenamed Operation Neptune and often referred to as D-Day (after the military term), it is the largest seaborne invasion in history.', 1944, 6, 6, 1944, 8, 29, 'day', '6 June 1944 – 29 August 1944', 81, 'https://en.wikipedia.org/wiki/Normandy_landings'),
  ('Q1164685', '1947 KLM Douglas DC-3 crash', 'The 1947 KLM Douglas DC-3 crash refers to the crash of a KLM Royal Dutch Airlines flight from Amsterdam to Stockholm via Copenhagen on 26 January. It occurred shortly after the Douglas DC-3 took off from Kastrup Airport in Denmark.', 1947, 1, 26, NULL, NULL, NULL, 'day', '26 January 1947', 52, 'https://en.wikipedia.org/wiki/1947_KLM_Douglas_DC-3_crash'),
  ('Q12338932', '1985 Copenhagen bombings by Hezbollah', 'On 22 July 1985, two bombs exploded in a terrorist attack in Copenhagen, Denmark. One of the bombs exploded near the Great Synagogue and a Jewish nursing home and kindergarten, and another at the offices of Northwest Orient Airlines.', 1985, 7, 22, NULL, NULL, NULL, 'day', '22 July 1985', 45, 'https://en.wikipedia.org/wiki/1985_Copenhagen_bombings'),
  ('Q2889830', 'Battle of Ryesgade', 'The Battle of Ryesgade was a nine-day series of street fights in mid-September 1986, in the Copenhagen street Ryesgade. It was the most violent event in a long-standing conflict between the Copenhagen City Council and the city''s community of squatters.', 1986, 9, 14, 1986, 9, 22, 'day', '14 September 1986 – 22 September 1986', 30, 'https://en.wikipedia.org/wiki/Battle_of_Ryesgade'),
  ('Q5219786', 'Danish Single European Act referendum, 1986', 'A non-binding referendum on the Single European Act was held in Denmark on 27 February 1986. It was approved by 56% of voters, with a voter turnout of 75%.', 1986, 2, 27, NULL, NULL, NULL, 'day', '27 February 1986', 34, 'https://en.wikipedia.org/wiki/1986_Danish_Single_European_Act_referendum'),
  ('Q3072357', 'Danish Maastricht Treaty referendum', 'A referendum on the Maastricht Treaty for the founding of the European Union was held in Denmark on 2 June 1992. The treaty was rejected by 50.7% of voters with a turnout of 83.1%.', 1992, 6, 2, NULL, NULL, NULL, 'day', '2 June 1992', 41, 'https://en.wikipedia.org/wiki/1992_Danish_Maastricht_Treaty_referendum'),
  ('Q4993694', 'Danish Maastricht Treaty referendum', 'A second referendum on the Maastricht Treaty was held in Denmark on 18 May 1993. After rejecting the treaty in a referendum the previous year, this time it was approved by 56.7% of voters with an 86.5% turnout.', 1993, 5, 18, NULL, NULL, NULL, 'day', '18 May 1993', 39, 'https://en.wikipedia.org/wiki/1993_Danish_Maastricht_Treaty_referendum'),
  ('Q585524', 'Danish euro referendum, 2000', 'A referendum on joining the Eurozone was held in Denmark on 28 September 2000. It was rejected by 53.2% of voters with a turnout of 87.60%.', 2000, 9, 28, NULL, NULL, NULL, 'day', '28 September 2000', 45, 'https://en.wikipedia.org/wiki/2000_Danish_euro_referendum'),
  ('Q182865', 'War in Afghanistan (2001–2021)', 'The war in Afghanistan was a prolonged armed conflict from 2001 to 2021. It began with an invasion by a United States–led coalition under the name Operation Enduring Freedom in response to the September 11 attacks (9/11) carried out by the Taliban-allied and Afghanistan-based al-Qaeda.', 2001, 10, 7, 2021, 8, 30, 'day', '7 October 2001 – 30 August 2021', 84, 'https://en.wikipedia.org/wiki/War_in_Afghanistan_(2001%E2%80%932021)'),
  ('Q545449', 'Iraq War', 'The Iraq War (Arabic: حرب العراق, romanized: ḥarb al-ʿirāq), also referred to as the Second Gulf War (Gulf War II), was a protracted armed conflict in Iraq from 2003 to 2011. It began in March 2003 with the invasion by a United States–led coalition, which resulted in the overthrow of the Ba''athist government of Saddam Hussein.', 2003, 3, 20, 2011, 12, 15, 'day', '20 March 2003 – 15 December 2011', 89, 'https://en.wikipedia.org/wiki/Iraq_War'),
  ('Q15694177', 'Danish Unified Patent Court membership referendum, 2014', 'A referendum on joining the Unified Patent Court was held in Denmark on 25 May 2014 alongside European Parliament elections. The referendum was approved with 62.5% of the vote, enabling the government to proceed with the ratification of the Agreement on a Unified Patent Court, which constitutes the legal basis for the Unified Patent Court.', 2014, 5, 25, NULL, NULL, NULL, 'day', '25 May 2014', 37, 'https://en.wikipedia.org/wiki/2014_Danish_Unified_Patent_Court_membership_referendum'),
  ('Q21014503', 'Danish European Union opt-out referendum, 2015', 'A referendum on one of the country''s opt-outs from the European Union was held in Denmark on 3 December 2015. Specifically, the referendum was on whether to convert Denmark''s current full opt-out on home and justice matters into an opt-out with case-by-case opt-in similar to those held by Ireland and the United Kingdom.', 2015, 12, 3, NULL, NULL, NULL, 'day', '3 December 2015', 39, 'https://en.wikipedia.org/wiki/2015_Danish_European_Union_opt-out_referendum'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe'),
  ('Q111136377', '2022 Danish European Union opt-out referendum', 'A referendum on the abolition of the defence opt-out, one of the country''s opt-outs from the European Union, was held in Denmark on 1 June 2022. The referendum was announced on 6 March 2022 following a broad multi-party defence agreement reached during the 2022 Russian invasion of Ukraine.', 2022, 6, 1, NULL, NULL, NULL, 'day', '1 June 2022', 56, 'https://en.wikipedia.org/wiki/2022_Danish_European_Union_opt-out_referendum');
